static int r8152_mdio_test_and_clr_bit(struct r8152 *tp, u16 addr, u16 clear)
{
	int data, ret;

	ret = r8152_mdio_read(tp, addr);
	if (ret < 0)
		goto out;

	data = ret;
	if (data & clear) {
		data &= ~clear;
		ret = r8152_mdio_write(tp, addr, data);
		if (ret < 0)
			goto out;
	}

	ret = !!(data & clear);

out:
	return ret;
}
